// The real store modules (store/index.js: createStoreContext) against a throwaway Radicale that runs the PRODUCTION
// rights plugin with rights generated by the REAL backend (tests/integration/dav/stack.py): alice owns the books, bob
// holds a read-write grant on one of them, agent-1 a read grant. Contacts: sync, outside edits, the write path
// (saveItem / createItem / copyItem / deleteItem / putGroupMembers) with a REAL 412 and every resolution, the review
// regressions C1 and M2 against the real server, permissions, group cleanup and a 2,000-contact scale smoke test.
import assert from 'node:assert/strict';
import { newRow, toFormValues, toPatch } from '../../../src/js/contacts/formmodel.js';
import { openItem } from '../../../src/js/model/item.js';
import { account, appleGroup, itp, lf, lines, membersOf, newBook, openStore, pool, rfcGroup, serverCards, SKIP_SCALE, urn, uuid, vcard } from './prodenv.mjs';
import { fictionalCard } from './gen.mjs';

/** What the contact form does on opening a store entry: {base, baseFields, values}. */
function openForm(store, href) {
  const e = store.get(href);
  const item = openItem(e.text, 'contact');
  const baseFields = item.fields();
  return { base: { text: e.text, etag: e.etag }, baseFields, values: toFormValues(baseFields) };
}
const patchOf = (form) => toPatch(form.baseFields, form.values);

/** alice (store, writes), bob and agent-1 on one fresh book; one card `href` created through alice's write path. */
async function scene({ fn = 'Rae Rebase' } = {}) {
  const book = await newBook('alice', { bob: 'readwrite', 'agent-1': 'read' });
  const alice = account('alice');
  const bob = account('bob');
  await alice.ctx.access.refetch();
  await bob.ctx.access.refetch();
  const made = await alice.ctx.writes.createItem({ collection: book.href, kind: 'contact', fields: { fn, tel: [{ value: '+1 555 0131', types: ['cell'] }, { value: '+1 555 0132', types: ['work'] }], email: [{ value: 'rae@example.org', types: ['home'] }], note: 'Original note' } });
  assert.equal(made.status, 'created', JSON.stringify(made));
  const aliceStore = await openStore(alice, book.href);
  const bobStore = await openStore(bob, book.href);
  return { book, alice, bob, aliceStore, bobStore, href: made.href, dispose: async () => { await alice.dispose(); await bob.dispose(); } };
}

/** bob changes the card through HIS write path (as another client would) and syncs. */
async function bobEdits(s, edit) {
  const form = openForm(s.bobStore, s.href);
  edit(form.values, form.baseFields);
  const r = await s.bob.ctx.writes.saveItem({ collection: s.book.href, href: s.href, patch: patchOf(form), baseFields: form.baseFields, base: form.base });
  assert.equal(r.status, 'saved', JSON.stringify(r));
  return r;
}

