for (const [label, make] of [['Apple form', appleGroup], ['RFC 6350 form', rfcGroup]]) {
  itp(`group membership through the write path, ${label}: one PUT on the group card, member cards byte-identical, a stale base rebases as a delta`, async () => {
    const book = await newBook('alice', { bob: 'readwrite' });
    const alice = account('alice');
    const bob = account('bob');
    try {
      await alice.ctx.access.refetch();
      await bob.ctx.access.refetch();
      for (const [n, fn] of [[1, 'Mia Member'], [2, 'Ned Newcomer'], [3, 'Oda Other'], [4, 'Pat Plus']]) await alice.client.putItem(`${book.href}m${n}.vcf`, vcard(n, fn), { create: true });
      const unknown = 'mailto:agent-1@example.org';
      await alice.client.putItem(`${book.href}group.vcf`, make(20, 'Chess club', [urn(1), unknown]), { create: true });
      const store = await openStore(alice, book.href);
      const bobStore = await openStore(bob, book.href);
      const g = `${book.href}group.vcf`;
      const memberCards = async () => (await serverCards(alice.client, book.href)).filter((e) => !/KIND:group/i.test(e.text)).map((e) => `${e.href}|${e.etag}|${e.text}`);
      const before = await memberCards();

      // add Ned: ONE PUT, on the group card only
      const mark = alice.mark();
      const r = await alice.ctx.writes.putGroupMembers({ collection: book.href, href: g, delta: { add: [uuid(2)] } });
      assert.equal(r.status, 'saved', JSON.stringify(r));
      assert.equal(r.verified, true);
      assert.deepEqual(alice.puts(mark).map((p) => p.path), [g]);
      assert.deepEqual(membersOf((await alice.client.getItem(g)).text), [urn(1), urn(2), unknown].sort());
      assert.deepEqual(await memberCards(), before, 'member cards: same bytes, same ETags');
      assert.equal(store.get(g).text, (await alice.client.getItem(g)).text);

      // bob adds Oda from a stale copy (his store never synced): the 412 is rebased as a delta, once
      const stale = bobStore.get(g);
      const rb = await bob.ctx.writes.putGroupMembers({ collection: book.href, href: g, delta: { add: [uuid(3)] }, base: { text: stale.text, etag: stale.etag } });
      assert.equal(rb.status, 'saved', JSON.stringify(rb));
      assert.deepEqual(membersOf((await alice.client.getItem(g)).text), [urn(1), urn(2), urn(3), unknown].sort(), 'their member (Ned) and mine both stand');

      // remove Mia and the unknown member (by exact URI): only those lines go
      // (alice's own copy is stale now: bob saved. The 412 is rebased once, as a delta, and succeeds.)
      const rm = await alice.ctx.writes.putGroupMembers({ collection: book.href, href: g, delta: { remove: [uuid(1), unknown] }, base: store.get(g) });
      assert.equal(rm.status, 'saved', JSON.stringify(rm));
      assert.deepEqual(membersOf((await alice.client.getItem(g)).text), [urn(2), urn(3)].sort(), 'Mia and the unknown member are gone, bob\'s and my additions stay');
      assert.deepEqual(await memberCards(), before, 'member cards untouched after the removals too');
    } finally {
      await alice.dispose();
      await bob.dispose();
    }
  });
}

itp('createItem of a group card takes the form the book already uses; groups never change member cards', async () => {
  const book = await newBook('alice');
  const alice = account('alice');
  try {
    await alice.ctx.access.refetch();
    await alice.client.putItem(`${book.href}m1.vcf`, vcard(1, 'Mia Member', '', '4.0'), { create: true });
    await alice.client.putItem(`${book.href}g0.vcf`, rfcGroup(30, 'Existing RFC group', [urn(1)]), { create: true });
    const store = await openStore(alice, book.href);
    const before = (await serverCards(alice.client, book.href)).find((e) => /Mia Member/.test(e.text));
    const r = await alice.ctx.writes.createItem({ collection: book.href, group: { name: 'New group', memberUids: [uuid(1)] } });
    assert.equal(r.status, 'created', JSON.stringify(r));
    const text = (await alice.client.getItem(r.href)).text;
    assert.ok(lines(text).includes('KIND:group'), 'RFC form like the existing group');
    assert.deepEqual(membersOf(text), [urn(1)]);
    assert.equal(r.verified, true);
    const after = (await serverCards(alice.client, book.href)).find((e) => /Mia Member/.test(e.text));
    assert.deepEqual(after, before);
    assert.equal(store.size, 3);
    // a group card cannot be saved as a copy after a conflict
    const entry = store.get(r.href);
    const c = await alice.ctx.writes.copyItem({ collection: book.href, href: r.href, patch: { fn: 'Renamed' }, base: { text: entry.text, etag: entry.etag } });
    assert.equal(c.status, 'not-allowed');
  } finally {
    await alice.dispose();
  }
});

itp('bulk delete with group cleanup: every deleted contact leaves both group forms, nobody else changes', async () => {
  const book = await newBook('alice');
  const alice = account('alice');
  try {
    await alice.ctx.access.refetch();
    const N = 12;
    for (let n = 1; n <= N; n++) await alice.client.putItem(`${book.href}c${n}.vcf`, vcard(n, `Person${String.fromCharCode(64 + n)} Example`), { create: true });
    const unknown = 'mailto:agent-1@example.org';
    const apple = [1, 2, 3, 4, 5, 6, 7, 8].map(urn);
    const rfc = [3, 4, 5, 6, 9, 10].map(urn).concat(unknown);
    await alice.client.putItem(`${book.href}ga.vcf`, appleGroup(101, 'Apple group', apple), { create: true });
    await alice.client.putItem(`${book.href}gr.vcf`, rfcGroup(102, 'RFC group', rfc), { create: true });
    const store = await openStore(alice, book.href);
    assert.equal(store.size, N + 2);
    const doomed = [1, 3, 4, 5, 6, 9];
    const survivors = serverCardsMap((await serverCards(alice.client, book.href)).filter((c) => /\/c\d+\.vcf$/.test(c.href)), doomed.map((n) => `${book.href}c${n}.vcf`));
    const mark = alice.mark();
    const results = [];
    for (const n of doomed) {
      const e = store.get(`${book.href}c${n}.vcf`);
      results.push(await alice.ctx.writes.deleteItem({ collection: book.href, href: e.href, etag: e.etag }));
    }
    assert.deepEqual(results.map((r) => r.status), doomed.map(() => 'deleted'));
    assert.ok(results.every((r) => r.cleanupFailed === 0));
    // only the groups that listed the contact were written
    const expectedPuts = doomed.reduce((s, n) => s + (apple.includes(urn(n)) ? 1 : 0) + (rfc.includes(urn(n)) ? 1 : 0), 0);
    const puts = alice.puts(mark).filter((p) => /\/g[ar]\.vcf$/.test(p.path));
    assert.equal(puts.length, expectedPuts, 'one PUT per (deleted contact, group that lists it)');
    assert.equal(alice.puts(mark).length, expectedPuts, 'no other card was written');
    const cards = await serverCards(alice.client, book.href);
    assert.equal(cards.length, N - doomed.length + 2);
    const gA = cards.find((e) => /Apple group/.test(e.text));
    const gR = cards.find((e) => /RFC group/.test(e.text));
    assert.deepEqual(membersOf(gA.text), [2, 7, 8].map(urn).sort());
    assert.deepEqual(membersOf(gR.text), [urn(10), unknown].sort());
    // surviving contacts are byte-identical
    for (const c of cards) if (survivors.has(c.href)) assert.equal(c.text, survivors.get(c.href).text);
    assert.deepEqual(store.list().map((e) => e.href).sort(), cards.map((e) => e.href).sort(), 'the store agrees with the server');
  } finally {
    await alice.dispose();
  }
});
/** Map of href -> card for the cards that are NOT in `except`. */
function serverCardsMap(cards, except) {
  return new Map(cards.filter((c) => !except.includes(c.href)).map((c) => [c.href, c]));
}

// ---------------------------------------------------------------------------
// Permissions through the application layer

itp('a read-write grantee saves and deletes; collection management is the owner\'s (guard and server agree)', async () => {
  const s = await scene();
  try {
    // bob, read-write: saves a card (done in bobEdits) and may not manage the collection
    await bobEdits(s, (v) => void (v.title = 'Set by bob'));
    const mark = s.bob.mark();
    const pp = await s.bob.ctx.writes.proppatch({ href: s.book.href, kind: 'addressbook', changes: { displayName: 'Renamed by bob' } });
    assert.equal(pp.status, 'readonly');
    const del = await s.bob.ctx.writes.deleteCollection({ href: s.book.href, kind: 'addressbook' });
    assert.equal(del.status, 'readonly');
    assert.equal(s.bob.since(mark, { via: 'dav' }).length, 0, 'known level: nothing sent');
    // the SERVER refuses the same requests when the layer is bypassed
    const raw = s.bob.client;
    await assert.rejects(raw.proppatch(s.book.href, 'addressbook', { displayName: 'Renamed by bob' }), (e) => e.kind === 'forbidden' && e.status === 403);
    const col = await raw.getCollection(s.book.href);
    await assert.rejects(raw.deleteCollection(s.book.href, col.etag), (e) => e.kind === 'forbidden' && e.status === 403);
    assert.equal((await s.alice.client.getCollection(s.book.href)).displayName, s.book.name, 'untouched');
    // bob deletes a card (rw can delete items)
    const e = s.bobStore.get(s.href);
    await s.bobStore.refresh();
    const fresh = s.bobStore.get(s.href);
    assert.equal((await s.bob.ctx.writes.deleteItem({ collection: s.book.href, href: s.href, etag: fresh.etag })).status, 'deleted');
    void e;
  } finally {
    await s.dispose();
  }
});

