// 2,000 contacts

itp('scale smoke test: 2,000 contacts seeded by PUT, a warm-up read, load, search, one edit and an incremental sync', { skip: SKIP_SCALE, timeout: 300000 }, async (t) => {
  const N = 2000;
  const book = await newBook('alice', {}, { tag: 'scale' });
  const alice = account('alice');
  try {
    await alice.ctx.access.refetch();
    const t0 = Date.now();
    await pool(N, async (i) => {
      await alice.client.putItem(`${book.href}c${i}.vcf`, fictionalCard(i), { create: true });
    }, 8);
    const seeded = Date.now() - t0;
    // warm-up read (a book that was not written through Radicale's PUT pays a cold cache on its first read)
    const w0 = Date.now();
    const warm = await alice.client.listItemEtags(book.href);
    const warmup = Date.now() - w0;
    assert.equal(warm.length, N);
    const { summarize, buildList } = await import('../../../src/js/contacts/index.js');
    const summaries = [];
    const store = alice.ctx.stores.open({ href: book.href, kind: 'addressbook' }, { indexer: (text, href) => void summaries.push(summarize(text, { href })) });
    const l0 = Date.now();
    const first = await store.sync({ reason: 'load' });
    const load = Date.now() - l0;
    assert.equal(first.ok, true);
    assert.equal(store.size, N);
    assert.equal(summaries.length, N);
    const r0 = Date.now();
    const again = await store.reload();
    const reload = Date.now() - r0;
    assert.equal(again.ok, true);
    assert.equal(store.size, N);
    const rss = Math.round(process.memoryUsage().rss / 1048576);
    const b0 = Date.now();
    const list = buildList(summaries.slice(-N), { lang: 'en' });
    const q0 = Date.now();
    const hits = buildList(summaries.slice(-N), { lang: 'en', query: 'example.org' });
    const search = Date.now() - q0;
    assert.ok(list.rows.length >= 1900 && hits.rows.length > 0);
    // one edit and an incremental sync
    const href = `${book.href}c7.vcf`;
    const e = store.get(href);
    const mark = alice.mark();
    const s0 = Date.now();
    const saved = await alice.ctx.writes.saveItem({ collection: book.href, href, patch: { note: 'edited' }, base: { text: e.text, etag: e.etag } });
    const save = Date.now() - s0;
    assert.equal(saved.status, 'saved');
    const i0 = Date.now();
    const inc = await store.sync({ reason: 'poll' });
    const incremental = Date.now() - i0;
    assert.equal(inc.ok, true);
    assert.ok(alice.since(mark, { method: 'REPORT' }).length >= 1);
    t.diagnostic(`2000 contacts: seed ${seeded} ms (8 in flight), warm-up listing ${warmup} ms, first load ${load} ms, reload ${reload} ms, build list ${Date.now() - b0 - search} ms, search ${search} ms, save ${save} ms, incremental sync ${incremental} ms, test process RSS ${rss} MB`);
    assert.ok(load < 120000, 'first load within the budget');
    assert.ok(incremental < 5000, 'an incremental sync is quick');
    assert.ok(search < 2000, 'search over 2,000 summaries is quick');
  } finally {
    await alice.dispose();
  }
});
